use std::sync::{Arc,Mutex};
use vybe_runtime::{Chunk,Op,Value,VM,value::Object};
use vybe_compiler::primitives::{expressions,functions,instructions::core_wasm,platforms,generators};
fn vm()->VM{let mut v=VM::new();platforms::register_platforms_all(&mut v);v}
fn callable(v:&mut VM,label:&str,answer:Value,events:Arc<Mutex<Vec<String>>>,arity:u8)->Value{let key=label.to_owned();let name=label.to_owned();v.register_host_fn("test:optional",label,Box::new(move|_,_|{events.lock().unwrap().push(name.clone());answer.clone()}));let mut root=Chunk::new("<optional-callback-owner>");functions::emit_ref_func(&mut root,1,0,17);root.emit_op(Op::RETURN,17);let mut c=Chunk::new(label);c.arity=arity;c.param_count=arity;c.local_count=arity.into();let i=c.add_import("test:optional",key);c.emit_call(i,0,17);c.emit_op(Op::RETURN,17);v.run(vec![root,c]).unwrap()}
fn property(o:&mut Object,key:&str,getter:Value){o.properties.insert(format!("__get_{key}"),getter);}
fn module(kind:u8)->Vec<Chunk>{let mut root=Chunk::new("<optional-probe-owner>");functions::emit_ref_func(&mut root,1,0,31);root.emit_op(Op::RETURN,31);let mut c=Chunk::new("optional_probe");c.arity=2;c.param_count=2;c.local_count=2;let mut cs=vec![root,c];match kind{0=>expressions::emit_rich_compare_locals(&mut cs,1,0,1,"__lt__",expressions::RichFallback::Op(|c,l|{c.emit_op(Op::DROP,l);c.emit_op(Op::DROP,l);c.emit_bool_const(false,l);}),31,false),1=>expressions::emit_smart_length(&mut cs[1],0,31),2|3=>{cs[1].emit_op_u16(Op::LOCAL_GET,0,31);if kind==2{generators::emit_drain_custom_iterable(&mut cs,1,31)}else{generators::emit_drain_async_iterable(&mut cs,1,31)}},_=>unreachable!()}cs[1].emit_op(Op::RETURN,31);cs}
#[test]fn comparison_absence_order_and_invalid_present_values(){for invalid in [None,Some(Value::Bool(false)),Some(Value::I32(0))]{let mut v=vm();let events=Arc::new(Mutex::new(vec![]));let mut o=Object::new();for key in ["__lt__","compare","CompareTo","compareTo","__cmp__","<=>"]{let value=if key=="__lt__"{invalid.clone().unwrap_or(Value::Undefined)}else{Value::Undefined};let get=callable(&mut v,key,value,events.clone(),1);property(&mut o,key,get);}let f=v.run(module(0)).unwrap();let r=v.invoke(&f,&[Value::Object(vybe_runtime::heap::alloc(o)),Value::F64(2.0)]);if invalid.is_none(){assert_eq!(r.unwrap(),Value::Bool(false));assert_eq!(*events.lock().unwrap(),vec!["__lt__","compare","CompareTo","compareTo","__cmp__","<=>"]);}else{let e=r.err().expect("present false/zero method invoked");assert!(e.call_stack.iter().any(|s|s.chunk_name=="optional_probe"));assert_eq!(*events.lock().unwrap(),vec!["__lt__"]);}}}
#[test]fn smart_length_absence_order_and_invalid_present_values(){for invalid in [None,Some(Value::Bool(false)),Some(Value::I32(0))]{let mut v=vm();let events=Arc::new(Mutex::new(vec![]));let mut o=Object::new();let m=callable(&mut v,"length_method",Value::I32(3),events.clone(),1);let lenkey=vybe_ast::protocol_slot_key(vybe_ast::ProtocolSlot::Len);let get=callable(&mut v,"len_get",invalid.clone().unwrap_or(Value::Undefined),events.clone(),1);property(&mut o,&lenkey,get);let get=callable(&mut v,"property_get",m,events.clone(),1);property(&mut o,"__get_length",get);let f=v.run(module(1)).unwrap();let r=v.invoke(&f,&[Value::Object(vybe_runtime::heap::alloc(o)),Value::Null]);if invalid.is_none(){assert_eq!(r.unwrap(),Value::I32(3));assert_eq!(*events.lock().unwrap(),vec!["len_get","property_get","length_method"]);}else{r.err().expect("present false/zero Len invoked");assert_eq!(*events.lock().unwrap(),vec!["len_get"]);}}}
#[test]fn iterator_absence_lookup_order_and_present_false_zero(){for async_ in [false,true]{for invalid in [None,Some(Value::Bool(false)),Some(Value::I32(0))]{let mut v=vm();let events=Arc::new(Mutex::new(vec![]));let mut o=Object::new();let mut step=Object::new();step.properties.insert("done".into(),Value::Bool(true));let next=callable(&mut v,"next_method",Value::Object(vybe_runtime::heap::alloc(step)),events.clone(),1);let mut iterator=Object::new();let get=callable(&mut v,"iterator_next_get",next,events.clone(),1);property(&mut iterator,"next",get);let it=callable(&mut v,"iterator_method",Value::Object(vybe_runtime::heap::alloc(iterator)),events.clone(),1);for key in ["next","Symbol(@@asyncIterator)","asyncIterator","Symbol(@@iterator)","iterator"]{let value=if key=="next"{invalid.clone().unwrap_or(Value::Undefined)}else if key=="iterator"{it.clone()}else{Value::Undefined};let get=callable(&mut v,key,value,events.clone(),1);property(&mut o,key,get);}let object=Value::Object(vybe_runtime::heap::alloc(o));let r=if async_{let mut cs=module(3);let end=cs[0].code.len()-4;cs[0].code.truncate(end);v.register_host_fn("test:optional","argument",Box::new(move|_,_|object.clone()));let arg=cs[0].add_import("test:optional","argument");cs[0].emit_call(arg,0,31);core_wasm::emit_value(&mut cs[0],31,&Value::Null);vybe_compiler::primitives::callable::emit_direct_invoke_chunk(&mut cs[0],2,31);cs[0].emit_op(Op::RETURN,31);v.run(cs)}else{let f=v.run(module(2)).unwrap();v.invoke(&f,&[object,Value::Null])};if invalid.is_some(){r.err().expect("present invalidnext invocation");assert_eq!(*events.lock().unwrap(),vec!["next"]);}else{r.unwrap();let want=if async_{vec!["next","Symbol(@@asyncIterator)","asyncIterator","Symbol(@@iterator)","iterator","iterator_method","iterator_next_get","next_method"]}else{vec!["next","Symbol(@@iterator)","iterator","iterator_method","iterator_next_get","next_method"]};assert_eq!(*events.lock().unwrap(),want);}}}}
#[test]fn actual_python_len_cached_getter_precedence_and_false_zero(){vybe_language_python::register();let m=vybe_language_python::parse("def length_subject(x):\n    return len(x)\n").unwrap();let c=vybe_compiler::Compiler::with_profile(vybe_compiler::profile::parse_profile(vybe_language_python::profile_source()).unwrap()).compile(&m).unwrap();for state in [0,1,2,3]{let mut v=vm();v.run(c.clone()).unwrap();let f=v.global("length_subject").or_else(||v.global("__vybe_func$length_subject")).unwrap().clone();let events=Arc::new(Mutex::new(vec![]));let method=callable(&mut v,"length_method",Value::I32(4),events.clone(),1);let answer=match state{0=>Value::Undefined,1=>method.clone(),2=>Value::Bool(false),3=>Value::I32(0),_=>unreachable!()};let mut o=Object::new();let get=callable(&mut v,"slot_get",answer,events.clone(),1);property(&mut o,&vybe_ast::protocol_slot_key(vybe_ast::ProtocolSlot::Len),get);let get=callable(&mut v,"dunder_get",method,events.clone(),1);property(&mut o,"__len__",get);let r=v.invoke(&f,&[Value::Object(vybe_runtime::heap::alloc(o))]);if state<2{assert_eq!(r.unwrap(),Value::I32(4));assert_eq!(*events.lock().unwrap(),if state==0{vec!["slot_get","dunder_get","length_method"]}else{vec!["slot_get","length_method"]});}else{let e=r.err().expect("present invalidLen invokes");assert!(e.call_stack.iter().any(|s|s.chunk_name=="length_subject"));assert_eq!(*events.lock().unwrap(),vec!["slot_get"]);}}}
